import mailbox, os
SUBJECT_WORDS = {'join': ('join','subscribe'), 'leave': ('leave','unsubscri')}
def confirmations(user, kind=''):
    p = f'/var/mail/{user}'
    if not os.path.exists(p) or os.path.getsize(p) == 0:
        raise AssertionError('mailbox not delivered yet')
    words = SUBJECT_WORDS.get(kind, ('',))
    out=[]
    for m in mailbox.mbox(p):
        if not (m.get('From') or '').startswith('reading-group-confirm'):
            continue
        subj = (m.get('Subject') or '').lower()
        if any(w in subj for w in words):
            out.append(m)
    return out
r = confirmations('864a6b7bc2e4','leave')
print('leave matches:', len(r))
for m in r: print('  ', m['From'])
EOF

